import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"45、【萃】 坤下兑上","description":"周易口诀义 - 45、【萃】 坤下兑上","frontmatter":{"title":"45、【萃】 坤下兑上","description":"周易口诀义 - 45、【萃】 坤下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/047.md","filePath":"zh/classics/koujueyi/047.md"}'),r={name:"zh/classics/koujueyi/047.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_45、【萃】-坤下兑上" tabindex="-1">45、【萃】 坤下兑上 <a class="header-anchor" href="#_45、【萃】-坤下兑上" aria-label="Permalink to “45、【萃】 坤下兑上”">​</a></h1><p>彖曰：萃，聚也。顺以说，刚中而应，故聚也。「王假有庙」，致孝享也。「利见大人亨」，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。</p><p>象曰：泽上于地，萃。君子以除戎器，戒不虞。</p><p>初六：有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎。</p><p>象曰：「乃乱乃萃」，其志乱也。</p><p>六二：引吉，无咎。孚乃利用礿。</p><p>象曰：「引吉无咎」，中未变也。</p><p>六三：萃如嗟如，无攸利。往无咎，小吝。</p><p>象曰：「往无咎」，上巽也。</p><p>九四：大吉，无咎。</p><p>象曰：「大吉无咎」，位不当也。</p><p>九五：萃有位，无咎，匪孚，元永贞，悔亡。</p><p>象曰：「萃有位」，志未光也。</p><p>上六，赍咨涕洟，无咎。</p><p>象曰：「赍咨涕洟」，未安上也。</p><p>解读</p><p>「萃亨」者，萃，聚也，其犹王者有德，怀来万邦，人皆归之，故曰「萃」也。人既归己，即无所不通，故曰「萃亨」也。「王假有庙」者，假，至也，天下离散，虽则有庙，与无庙同，纵使享祭，神明不降。今王既有德，人神大同，孝德乃洽，王至此时，始可假有宗庙，故周弘正云：「鬼神享德，不在食也。」「利见大人，亨，利贞」者，当聚之时，必须德大之人而为其主，故书云：「惟天生民有欲，无主乃乱」，故曰「利见大人」也。大德之人，能弘正道，即使下民亨通而利以为正，故曰「亨利贞」也。用大牲吉，利有攸往者，大牲，牺牛也；大德之人而为其主，聚道既全，即宜用大牲吉，利用攸往也。象曰「泽上于地，萃」者，泽处地上，水潦聚物，是萃聚象也。「君子以除戎器，戒不虞」者，除，治也，当大聚之时，虑恐人心有异，故曰君子亦修戎器，戒慎防备不虞，文聚武备是也。</p><p>「初六，有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎」者，初六应于九四，见六三与九四相近，心生嫌疑，始以诚信相就，忽然生疑未进，故曰「有孚不终」也。当萃之时，贵于合会，奔驰而往，进不以礼，故曰「乃乱乃萃」。夫谦恭之道，百行之本，若以谦而行，即无不合。今初六若执此谦逊，自比身云一握之小，又为柔懦卑劣之容，即六三邪偶，安能固守于四？即初六往必相得，不用忧虑，所以「无咎」，故曰「勿恤，往无咎」也。一握者，卑小之质，喻己身如一握之微小也；为笑者，懦劣之容，不敢作强刚之貌也。</p><p>「六二，引吉，无咎，孚乃利用礿」者，礿，殷春祭名，四时最薄也。处聚之时，贵相聚集，方始合宜。今六二体柔居坤，守中不变，意欲静退，不肯相从，以为聚会，斯乃违众，时即凶危必至，必须牵引，然后始行，遂得吉而免咎，故曰「引吉，无咎」。以六二体中怀信，不求苟进，既有斯德，即可以往，至薄之物，荐于鬼神，鬼神降福，故曰「孚乃利用礿」也。</p><p>「六三，萃如嗟如，无攸利，往无咎，小吝」者，六三与九四不正，不正相聚，阴邪之应，患必生焉，故乃忧嗟而无所利，故曰「萃如，无攸利」。然上六与三本是正应，上六怀巽之道，以求朋友，故六三可以往而无咎，与上合志而无所咎，故「往无咎」。然上六与三俱是阴柔，虽是相应，俱失其匹配之义，故有「小吝」也。九四，大吉，无咎。居位不正，又下据三阴，即擅君之权，祸咎将至，必须立大功以补其过，可以免咎，故曰「大吉，无咎」。</p><p>「九五，萃有位，无咎，匪孚，元永贞，悔亡」者，处聚之时，最得盛位，故曰「萃有位」也。九四下据三阴，专制己权，己所宣命，人不信服，但自守而已，故曰「无咎，匪孚」也。若能不与物竞，但自克修仁德，久而获福，即忧悔可销，故曰「元永贞悔亡」。</p><p>「上六：赍咨涕洟无咎」者，赍咨，嗟叹辞也。居萃之极，乘刚居上，内无应援，则忧患生焉，故赍咨涕泣不安。如此忧惧，即众所不害，遂将免咎，故曰「无咎」。先儒云：「自目曰涕，自鼻曰洟。」</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
